def csv_rows(text):
    rows = []
    i = 0
    n = len(text)

    while i < n:
        row = []
        # Skip empty lines at the very start or between rows
        # Actually, we need to parse field by field
        while True:
            # Parse a single field
            if i < n and text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                field_chars = []
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Doubled quote
                            field_chars.append('"')
                            i += 2
                        else:
                            # Closing quote
                            i += 1
                            break
                    else:
                        field_chars.append(text[i])
                        i += 1
                field = ''.join(field_chars)
            else:
                # Unquoted field
                field_chars = []
                while i < n and text[i] != ',' and text[i] != '\r' and text[i] != '\n':
                    field_chars.append(text[i])
                    i += 1
                field = ''.join(field_chars)

            row.append(field)

            # Check what comes after the field
            if i < n:
                if text[i] == ',':
                    i += 1  # skip comma, continue to next field in same row
                    continue
                elif text[i] == '\r':
                    if i + 1 < n and text[i + 1] == '\n':
                        i += 2  # skip CRLF
                    else:
                        i += 1  # skip lone CR
                    break  # end of row
                elif text[i] == '\n':
                    i += 1  # skip LF
                    break  # end of row
                else:
                    # Should not happen in valid CSV, but break just in case
                    break
            else:
                break  # end of input

        rows.append(row)

        # After breaking from the inner while, check if we're at end of input
        if i >= n:
            break

    return rows
